class Solution {
    private boolean palindrome(String word){
        for(int left=0,right=word.length()-1;left<right;left++,right--)if(word.charAt(left)!=word.charAt(right))return false;
        return true;
    }
    public String firstPalindrome(String[] words){
        for(String word:words)if(palindrome(word))return word;
        return "";
    }
}

code.kotlin:
class Solution {
    private fun palindrome(word:String):Boolean{
        var left=0;
        var right=word.lastIndex;
        while(left<right)if(word[left++]!=word[right--])return false;
        return true
    };
    fun firstPalindrome(words:Array<String>)=words.firstOrNull{
        palindrome(it)
    }?:""
}

